export interface ViewSpec {
  path: string;
  view: string;
  index?: boolean;
  parentPath?: string;
}

export interface ViewNode {
  path: string;
  view: string;
  index: boolean;
  children: ViewNode[];
}

export function buildViewTree(specs: readonly ViewSpec[]): ViewNode[] {
  if (!Array.isArray(specs)) throw new TypeError("specs must be an array");
  const roots: ViewNode[] = [];
  const parents = new Map<string, ViewNode>();

  for (const spec of specs) {
    if (typeof spec !== "object" || spec === null ||
        typeof spec.path !== "string" || typeof spec.view !== "string" || spec.view.trim() === "") {
      throw new TypeError("malformed specification");
    }
    if (spec.index) continue;
    if (spec.path.trim() === "" || spec.parentPath !== undefined || parents.has(spec.path)) {
      throw new TypeError("invalid root specification");
    }
    const node: ViewNode = { path: spec.path, view: spec.view, index: false, children: [] };
    roots.push(node);
    parents.set(spec.path, node);
  }

  for (const spec of specs) {
    if (!spec.index) continue;
    if (spec.path !== "" || typeof spec.parentPath !== "string") {
      throw new TypeError("invalid index specification");
    }
    const parent = roots[0];
    if (parent === undefined) throw new TypeError("missing parent");
    if (parent.children.some((child) => child.index)) throw new TypeError("duplicate index");
    parent.children.push({ path: "", view: spec.view, index: true, children: [] });
  }
  return roots;
}
