import { buildViewTree } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

assert(buildViewTree([]).length === 0, 'empty specifications');
const specs: any[] = [
  { path: '', view: 'Settings Home', index: true, parentPath: '/settings' },
  { path: '/users', view: 'Users' },
  { path: '/settings', view: 'Settings', index: false },
  { path: '', view: 'Users Home', index: true, parentPath: '/users' },
];
const tree = buildViewTree(specs);
equal(tree, [
  { path: '/users', view: 'Users', index: false, children: [
    { path: '', view: 'Users Home', index: true, children: [] },
  ] },
  { path: '/settings', view: 'Settings', index: false, children: [
    { path: '', view: 'Settings Home', index: true, children: [] },
  ] },
], 'root order, parent matching, and index order');
assert(tree !== specs && tree[0] !== specs[1] && tree[0].children[0] !== specs[3], 'new objects returned');
specs[1].view = 'Changed';
specs.push({ path: '/later', view: 'Later' });
assert(tree[0].view === 'Users' && tree.length === 2, 'input not retained');

throwsTypeError(() => buildViewTree(null as any), 'array required');
throwsTypeError(() => buildViewTree([{ path: '', view: 'Root' }]), 'root path must be nonblank');
throwsTypeError(() => buildViewTree([{ path: '/a', view: ' ' }]), 'view must be nonblank');
throwsTypeError(() => buildViewTree([{ path: '/a', view: 'A', parentPath: '/x' }]), 'root parent forbidden');
throwsTypeError(() => buildViewTree([{ path: '/a', view: 'A' }, { path: '/a', view: 'Again' }]), 'duplicate root path');
throwsTypeError(() => buildViewTree([{ path: '/a', view: 'A' }, { path: '/wrong', view: 'Index', index: true, parentPath: '/a' }]), 'index path must be empty');
throwsTypeError(() => buildViewTree([{ path: '', view: 'Index', index: true, parentPath: '/missing' }]), 'missing parent');
throwsTypeError(() => buildViewTree([
  { path: '/a', view: 'A' },
  { path: '', view: 'One', index: true, parentPath: '/a' },
  { path: '', view: 'Two', index: true, parentPath: '/a' },
]), 'duplicate index child');
throwsTypeError(() => buildViewTree([{ path: '/a', view: 'A', index: 'yes' as any }]), 'malformed index flag');

